steps.run:
node - <<'EOF'
const { execSync } = require("node:child_process");
const { createHash } = require("node:crypto");
const fs = require("node:fs");
const sha256 = (p) => createHash("sha256").update(fs.readFileSync(p)).digest("hex");
const sh = (c) => execSync(c, { encoding: "utf8" }).trim();
// dist digest: deterministic tar of the built artifact tree
execSync("tar --sort=name --mtime='UTC 2020-01-01' -cf /tmp/dist.tar dist");
const proof = {
  schema_version: "1.0",
  commit_sha: process.env.GITHUB_SHA,
  head_sha: process.env.PR_HEAD_SHA || process.env.GITHUB_SHA,
  tree_sha: sh("git rev-parse HEAD^{tree}"),
  workflow_sha: process.env.GITHUB_WORKFLOW_SHA,
  run_id: process.env.GITHUB_RUN_ID,
  runtime_versions: {
    node: sh("node --version"),
    pnpm: sh("pnpm --version"),
    typescript: require("typescript/package.json").version,
    vitest: require("vitest/package.json").version,
  },
  dependency_lock_hashes: {
    "pnpm-lock.yaml": sha256("pnpm-lock.yaml"),
    "ml/dime-1.0/uv.lock": sha256("ml/dime-1.0/uv.lock"),
  },
  artifact_digests: {
    "dist.tar": sha256("/tmp/dist.tar"),
    "dist/index.js": sha256("dist/index.js"),
  },
  checks: [
    { name: "frozen-install", outcome: "passed" },
    { name: "tsc", outcome: "passed" },
    { name: "vitest-gated", outcome: "passed", tests_passed: Number(process.env.TESTS_PASSED) },
    { name: "build+preview-gate+bundle-budget", outcome: "passed" },
  ],
  outcome: "passed",
};
fs.writeFileSync("proof-contract.json", JSON.stringify(proof, null, 2));
console.log(JSON.stringify(proof, null, 2));
EOF

# prompt-content assertions live in dimeChatModel.test.ts (above);
# here: the platform-knowledge catalog hashes cleanly (the hash is
# embedded into runtime prompts + Trace events)
node -e '
  const { createHash } = require("node:crypto");
  const fs = require("node:fs");
  const raw = fs.readFileSync("shared/dime/platform_knowledge_v1.json");
  JSON.parse(raw); // must be valid JSON
  console.log("platform_knowledge sha256:", createHash("sha256").update(raw).digest("hex"));
'

pnpm install --frozen-lockfile
node -e '
  const { execSync } = require("node:child_process");
  const pkg = require("./package.json");
  const deps = Object.keys({ ...pkg.dependencies, ...pkg.devDependencies });
  const cutoff = Date.now() - 14 * 864e5;
  const young = [];
  for (const d of deps) {
    try {
      const t = JSON.parse(execSync(`npm view ${d} time --json`, { stdio: ["ignore", "pipe", "ignore"] }));
      const versions = Object.entries(t).filter(([k]) => !["created", "modified"].includes(k));
      const latest = versions[versions.length - 1];
      if (latest && Date.parse(latest[1]) > cutoff) young.push(`${d}@${latest[0]} (${latest[1]})`);
    } catch {}
  }
  console.log(`packages with releases in the last 14 days: ${young.length}`);
  for (const y of young) console.log("  " + y);
'

npx --yes @stryker-mutator/core@9 run stryker.conf.json || {
  echo "::warning::mutation score below configured break threshold — review survivors above";
  exit 1;
}
